// Ukrainian is the source language of the game text. English is applied on the fly:
// every text node and label is matched against these patterns (dynamic messages) and
// then against known fragments, longest first. Switching language reloads the page.
const KEY='hatchglen-lang';
export const LANGS={uk:'Українська',en:'English'};
export let lang=(()=>{try{const v=localStorage.getItem(KEY);if(v==='uk'||v==='en')return v;}catch{}return (navigator.language||'uk').toLowerCase().startsWith('uk')?'uk':'en';})();
export function setLang(next){if(!LANGS[next]||next===lang)return;try{localStorage.setItem(KEY,next);}catch{}location.reload();}

